CREATE OR REPLACE FUNCTION public._sync_boss(_uid uuid, _bid uuid)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$ DECLARE b public.bosses; v numeric:=0; lv jsonb; total_day numeric; tz text; BEGIN SELECT * INTO b FROM public.bosses WHERE id=_bid; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_uid) OR NOT EXISTS(SELECT 1 FROM public.season_entries WHERE user_id=_uid AND season_id=b.season_id) THEN RETURN; END IF; SELECT timezone INTO tz FROM public.profiles WHERE id=_uid; PERFORM pg_advisory_xact_lock(hashtext(_uid::text||_bid::text)); INSERT INTO public.boss_entries(boss_id,user_id) VALUES(_bid,_uid) ON CONFLICT DO NOTHING;
IF b.metric='reps' THEN IF b.exercise_key='pullups' THEN SELECT greatest(coalesce((SELECT sum(ls.reps) FROM public.lift_sets ls JOIN public.lift_exercises ex ON ex.id=ls.exercise_id WHERE ls.user_id=_uid AND ex.key='pullups' AND ls.day=g.day),0),coalesce((SELECT sum(amount) FROM public.boss_hits WHERE user_id=_uid AND boss_id=_bid AND (created_at AT TIME ZONE tz)::date=g.day),0)) INTO total_day FROM (SELECT day FROM public.lift_sets WHERE user_id=_uid AND day BETWEEN (b.starts_at AT TIME ZONE tz)::date AND (b.ends_at AT TIME ZONE tz)::date UNION SELECT (created_at AT TIME ZONE tz)::date FROM public.boss_hits WHERE user_id=_uid AND boss_id=_bid) g ORDER BY 1 DESC LIMIT 1; v:=coalesce(total_day,0); ELSE SELECT greatest(coalesce((SELECT sum(ls.reps) FROM public.lift_sets ls JOIN public.lift_exercises ex ON ex.id=ls.exercise_id WHERE ls.user_id=_uid AND ex.equipment='dumbbell' AND ls.day BETWEEN (b.starts_at AT TIME ZONE tz)::date AND (b.ends_at AT TIME ZONE tz)::date),0),coalesce((SELECT sum(amount) FROM public.boss_hits WHERE user_id=_uid AND boss_id=_bid),0)) INTO v; END IF;
ELSIF b.metric='km' THEN SELECT greatest(coalesce((SELECT sum(CASE WHEN h.unit='mi' THEN ci.value*1.609344 ELSE ci.value END) FROM public.checkins ci JOIN public.user_habits h ON h.id=ci.user_habit_id JOIN public.habit_templates ht ON ht.id=h.template_id WHERE ci.user_id=_uid AND h.season_id=b.season_id AND ht.key=b.exercise_key AND ci.day BETWEEN (b.starts_at AT TIME ZONE tz)::date AND (b.ends_at AT TIME ZONE tz)::date),0),coalesce((SELECT sum(amount) FROM public.boss_hits WHERE user_id=_uid AND boss_id=_bid),0)) INTO v;
ELSIF b.metric='days' THEN IF b.exercise_key='completion' THEN SELECT count(*) INTO v FROM public.daily_scores WHERE user_id=_uid AND season_id=b.season_id AND completion>=1 AND day BETWEEN (b.starts_at AT TIME ZONE tz)::date AND (b.ends_at AT TIME ZONE tz)::date; ELSE SELECT count(DISTINCT ci.day) INTO v FROM public.checkins ci JOIN public.user_habits h ON h.id=ci.user_habit_id JOIN public.habit_templates ht ON ht.id=h.template_id WHERE ci.user_id=_uid AND h.season_id=b.season_id AND ht.key=b.exercise_key AND ci.value>=h.target AND ci.day BETWEEN (b.starts_at AT TIME ZONE tz)::date AND (b.ends_at AT TIME ZONE tz)::date; END IF;
ELSIF b.metric='posts' THEN SELECT count(*) INTO v FROM public.posts WHERE user_id=_uid AND season_id=b.season_id AND NOT hidden AND type IN ('thought','win') AND char_length(body)>=20 AND stats->>'boss_lesson'='true' AND created_at BETWEEN b.starts_at AND b.ends_at;
ELSE SELECT least(40,coalesce(sum(amount) FILTER(WHERE part='burpees'),0))+least(40,coalesce(sum(amount) FILTER(WHERE part='pullups'),0)) INTO v FROM public.boss_hits WHERE user_id=_uid AND boss_id=_bid; END IF;
UPDATE public.boss_entries SET progress=v WHERE boss_id=_bid AND user_id=_uid; SELECT l INTO lv FROM public.boss_entries e CROSS JOIN LATERAL jsonb_array_elements(b.levels) l WHERE e.boss_id=_bid AND e.user_id=_uid AND l->>'key'=e.level;
IF v>=(lv->>'target')::numeric AND public._account_now(_uid) BETWEEN b.starts_at AND b.ends_at THEN INSERT INTO public.bonus_points(user_id,season_id,boss_id,level,points) VALUES(_uid,b.season_id,_bid,lv->>'key',(lv->>'bonus')::int) ON CONFLICT(user_id,boss_id) DO UPDATE SET level=excluded.level,points=excluded.points,awarded_at=now() WHERE excluded.points>bonus_points.points; UPDATE public.boss_entries SET completed_at=coalesce(completed_at,public._account_now(_uid)) WHERE boss_id=_bid AND user_id=_uid; INSERT INTO public.badges(user_id,season_id,key) VALUES(_uid,b.season_id,'boss_ko') ON CONFLICT DO NOTHING; END IF; END $function$;
REVOKE ALL ON FUNCTION public._sync_boss(uuid,uuid) FROM PUBLIC, anon, authenticated;